def collatz_iter(k, n):
    result = n
    for _ in range(k):
        result = result // 2 if result % 2 == 0 else 3 * result + 1
    return result

def preimage_tree(m, depth):
    current = {m}
    for _ in range(depth):
        nxt = set()
        for v in current:
            nxt.add(2 * v)
            if (v - 1) % 3 == 0:
                c = (v - 1) // 3
                if c > 0 and c % 2 == 1:
                    nxt.add(c)
        current = nxt
    return current

def collatz_hash(x, depths, seeds):
    def step(n):
        return n // 2 if n % 2 == 0 else 3 * n + 1
    def iterate(k, n):
        for _ in range(k): n = step(n)
        return n
    return tuple(iterate(d, x + s) for d, s in zip(depths, seeds))
